import React, { useEffect, useState } from 'react';
import type { YearPerson } from '../year_types/YearTypes';
import { addToOrder } from '../year_api/YearApi';
import '../styles/historyPerson.css';

type Props = {
  person: YearPerson;
  // Если родитель явно знает про авторизацию, можно передать сюда.
  isAuthenticated?: boolean;
  // Если токен сохраняется под конкретным ключом в local/sessionStorage — можно передать его.
  tokenKey?: string;
};

const KNOWN_TOKEN_KEYS = ['token', 'authToken', 'history_token', 'accessToken', 'auth_token'];

export default function YearPersonCard({ person, isAuthenticated, tokenKey }: Props) {
  const staticById = `/images/historyPerson${person.id}.png`;
  const fallback = '/img.png';
  const src = person.image || staticById || fallback;

  const [isAdding, setIsAdding] = useState(false);
  const [isAuthState, setIsAuthState] = useState<boolean>(false);

  // Функция для чтения токена из storage
  function readTokenFromStorage(key?: string) {
    const tryKeys = key ? [key, ...KNOWN_TOKEN_KEYS] : KNOWN_TOKEN_KEYS;
    for (const k of tryKeys) {
      const v =
        typeof window !== 'undefined' &&
        (localStorage.getItem(k) ?? sessionStorage.getItem(k));
      if (v) return v;
    }
    return null;
  }

  // синхронный источник истины: пропс > storage
  useEffect(() => {
    if (typeof isAuthenticated === 'boolean') {
      setIsAuthState(isAuthenticated);
      return;
    }
    const token = readTokenFromStorage(tokenKey);
    setIsAuthState(Boolean(token));
  }, [isAuthenticated, tokenKey]);

  // слушаем изменения storage (когда логин/логаут в другой вкладке)
  useEffect(() => {
    function onStorage(e: StorageEvent) {
      // если изменился любой из ключей — перепроверяем
      if (!e.key || KNOWN_TOKEN_KEYS.includes(e.key) || e.key === tokenKey) {
        const token = readTokenFromStorage(tokenKey);
        setIsAuthState(Boolean(token));
      }
    }

    // кастомное событие, которое можно диспатчить после успешного логина:
    // window.dispatchEvent(new CustomEvent('history-login'));
    function onHistoryLogin() {
      const token = readTokenFromStorage(tokenKey);
      setIsAuthState(Boolean(token));
    }

    window.addEventListener('storage', onStorage);
    window.addEventListener('history-login', onHistoryLogin as EventListener);

    return () => {
      window.removeEventListener('storage', onStorage);
      window.removeEventListener('history-login', onHistoryLogin as EventListener);
    };
  }, [tokenKey]);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (isAdding) return;
    setIsAdding(true);
    try {
      const resp = await addToOrder(person.id);
      if (resp && (resp.ok || resp.status === 200)) {
        try {
          window.dispatchEvent(
            new CustomEvent('order-updated', { detail: { personId: person.id } })
          );
        } catch (_err) {
          // ignore
        }
        setIsAdding(false);
        return;
      }
      console.warn('addToOrder response:', resp);
      alert('Не удалось добавить в заявку');
    } catch (err) {
      console.error(err);
      alert('Ошибка при добавлении в заявку');
    } finally {
      setIsAdding(false);
    }
  }

  return (
    <div className="year-person-card">
      <div className="year-person-header">
        <div className="person-name">{person.person_name}</div>

        {isAuthState && (
          <form className="add-form" onSubmit={handleSubmit}>
            <button
              type="submit"
              className="add-button"
              disabled={isAdding}
              aria-label="Добавить в заявку"
            >
              {isAdding ? 'Добавляю…' : 'Добавить +'}
            </button>
          </form>
        )}
      </div>

      <hr />

      <div className="person-image-wrap">
        <img
          src={src}
          alt={person.person_name}
          onError={(e) => {
            (e.currentTarget as HTMLImageElement).src = fallback;
          }}
        />
      </div>

      <div className="person-years">
        <div>Годы правления</div>
        <p style={{ marginLeft: 0 }}>
          {person.year_from} — {person.year_to}
        </p>
      </div>

      <a href={`/person/${person.id}`} className="details-btn">
        Подробнее →
      </a>
    </div>
  );
}
